const lazy: Record<string, React.ComponentType> = Object.fromEntries(
  Object.entries(loaders).map(([name, load]) => [name, dynamic(load)])
)

// Examples go live when they come near the screen; see DeferredMount.
export function ClientExample({ name }: { name: string }) {
  if (!(name in loaders)) return null
  return <DeferredMount load={loaders[name]} fallback={lazy[name]} />
}
